import heapq

def astar(graph, h, start, goal):
    """graph[u] = list of (v, weight); h[v] = admissible estimate to goal."""
    g = {start: 0}
    parent = {}
    open_set = [(h[start], start)]
    closed = set()
    while open_set:
        f_u, u = heapq.heappop(open_set)
        if u in closed:
            continue
        closed.add(u)
        if u == goal:
            path = [goal]
            while path[-1] != start:
                path.append(parent[path[-1]])
            path.reverse()
            return path, g[goal]
        for v, w in graph[u]:
            tentative = g[u] + w
            if v not in g or tentative < g[v]:
                g[v] = tentative
                parent[v] = u
                heapq.heappush(open_set, (tentative + h[v], v))
    return None, float('inf')

if __name__ == "__main__":
    edges = [('S', 'A', 1), ('S', 'B', 4), ('A', 'B', 2),
             ('A', 'C', 5), ('B', 'C', 1), ('B', 'G', 5), ('C', 'G', 2)]
    graph = {n: [] for n in ['S', 'A', 'B', 'C', 'G']}
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))
    h = {'S': 5, 'A': 4, 'B': 2, 'C': 1, 'G': 0}
    path, cost = astar(graph, h, 'S', 'G')
    print(path, cost)
